#!/usr/bin/env bash
#
# A wizard walks a human through setting up AWS S3, Snowflake, and PostgreSQL credentials.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=3

banner "Saudi eCommerce Platform: Cloud & Database Setup"

# ── Stage 1: AWS S3 Data Lake & IAM Credentials ──────────────────────────
stage "AWS S3 Data Lake & IAM Credentials"
say "We will capture your AWS IAM access keys and target S3 data lake bucket."
open_url "https://console.aws.amazon.com/iam/home#/security_credentials"
step "In the AWS Console, navigate to IAM → Security Credentials → Access keys."
step "Click 'Create access key', select 'CLI' or 'Application running outside AWS'."
step "Copy the Access Key ID (starts with AKIA...)."
ask AWS_ACCESS_KEY_ID "Paste AWS Access Key ID:"

step "Click 'Show secret access key' and copy it."
ask_secret AWS_SECRET_ACCESS_KEY "Paste AWS Secret Access Key:"

step "Specify your target AWS region (e.g. me-central-1 for Riyadh, eu-west-1 for Ireland)."
ask AWS_DEFAULT_REGION "AWS Default Region [me-central-1]:"
AWS_DEFAULT_REGION="${AWS_DEFAULT_REGION:-me-central-1}"

step "Specify your S3 Data Lake bucket name (holds raw/ and processed/ zones)."
open_url "https://s3.console.aws.amazon.com/s3/home"
ask ENV_STORAGE_BUCKET "S3 Bucket Name [saudi-ecommerce-data-lake-dev]:"
ENV_STORAGE_BUCKET="${ENV_STORAGE_BUCKET:-saudi-ecommerce-data-lake-dev}"

write_env AWS_ACCESS_KEY_ID "$AWS_ACCESS_KEY_ID"
write_env AWS_SECRET_ACCESS_KEY "$AWS_SECRET_ACCESS_KEY"
write_env AWS_DEFAULT_REGION "$AWS_DEFAULT_REGION"
write_env ENV_STORAGE_BUCKET "$ENV_STORAGE_BUCKET"

set_secret AWS_ACCESS_KEY_ID "$AWS_ACCESS_KEY_ID"
set_secret AWS_SECRET_ACCESS_KEY "$AWS_SECRET_ACCESS_KEY"
set_var AWS_DEFAULT_REGION "$AWS_DEFAULT_REGION"
set_var ENV_STORAGE_BUCKET "$ENV_STORAGE_BUCKET"

# ── Stage 2: Snowflake Cloud Data Warehouse ──────────────────────────────
stage "Snowflake Cloud Data Warehouse"
say "We will configure your Snowflake account identifier, user, and database targets."
open_url "https://app.snowflake.com"
step "Log in to Snowflake (Snowsight). In bottom-left corner, click your profile → Account → Copy Account Identifier."
note "Example format: orgname-accountname or locator.region (e.g. xy12345.me-central-1)"
ask SNOWFLAKE_ACCOUNT "Paste Snowflake Account Identifier:"

step "Enter your Snowflake login username."
ask SNOWFLAKE_USER "Snowflake Username:"

step "Enter your Snowflake user password."
ask_secret SNOWFLAKE_PASSWORD "Snowflake Password:"

step "Specify your Snowflake Role (default: SYSADMIN)."
ask SNOWFLAKE_ROLE "Snowflake Role [SYSADMIN]:"
SNOWFLAKE_ROLE="${SNOWFLAKE_ROLE:-SYSADMIN}"

step "Specify your Snowflake Compute Warehouse (default: COMPUTE_WH)."
ask SNOWFLAKE_WAREHOUSE "Snowflake Warehouse [COMPUTE_WH]:"
SNOWFLAKE_WAREHOUSE="${SNOWFLAKE_WAREHOUSE:-COMPUTE_WH}"

step "Specify your Snowflake Database (default: SAUDI_ECOM_DW)."
ask SNOWFLAKE_DATABASE "Snowflake Database [SAUDI_ECOM_DW]:"
SNOWFLAKE_DATABASE="${SNOWFLAKE_DATABASE:-SAUDI_ECOM_DW}"

step "Specify your default staging Schema (default: RAW_STAGING)."
ask SNOWFLAKE_SCHEMA "Snowflake Schema [RAW_STAGING]:"
SNOWFLAKE_SCHEMA="${SNOWFLAKE_SCHEMA:-RAW_STAGING}"

write_env SNOWFLAKE_ACCOUNT "$SNOWFLAKE_ACCOUNT"
write_env SNOWFLAKE_USER "$SNOWFLAKE_USER"
write_env SNOWFLAKE_PASSWORD "$SNOWFLAKE_PASSWORD"
write_env SNOWFLAKE_ROLE "$SNOWFLAKE_ROLE"
write_env SNOWFLAKE_WAREHOUSE "$SNOWFLAKE_WAREHOUSE"
write_env SNOWFLAKE_DATABASE "$SNOWFLAKE_DATABASE"
write_env SNOWFLAKE_SCHEMA "$SNOWFLAKE_SCHEMA"

set_secret SNOWFLAKE_PASSWORD "$SNOWFLAKE_PASSWORD"
set_secret SNOWFLAKE_USER "$SNOWFLAKE_USER"
set_var SNOWFLAKE_ACCOUNT "$SNOWFLAKE_ACCOUNT"
set_var SNOWFLAKE_ROLE "$SNOWFLAKE_ROLE"
set_var SNOWFLAKE_WAREHOUSE "$SNOWFLAKE_WAREHOUSE"
set_var SNOWFLAKE_DATABASE "$SNOWFLAKE_DATABASE"

# ── Stage 3: Transactional PostgreSQL Database (Source) ──────────────────
stage "Transactional PostgreSQL Database (Local / Source)"
say "Configure connection details for the source database holding operational orders."
note "Default values align with the project's local docker-compose configuration."

step "Specify PostgreSQL Host (default: localhost)."
ask POSTGRES_HOST "Postgres Host [localhost]:"
POSTGRES_HOST="${POSTGRES_HOST:-localhost}"

step "Specify PostgreSQL Port (default: 5432)."
ask POSTGRES_PORT "Postgres Port [5432]:"
POSTGRES_PORT="${POSTGRES_PORT:-5432}"

step "Specify PostgreSQL Database name (default: saudi_ecom_orders)."
ask POSTGRES_DB "Postgres Database [saudi_ecom_orders]:"
POSTGRES_DB="${POSTGRES_DB:-saudi_ecom_orders}"

step "Specify PostgreSQL User (default: postgres)."
ask POSTGRES_USER "Postgres User [postgres]:"
POSTGRES_USER="${POSTGRES_USER:-postgres}"

step "Specify PostgreSQL Password (default: postgres)."
ask_secret POSTGRES_PASSWORD "Postgres Password [Enter keeps default]:"
POSTGRES_PASSWORD="${POSTGRES_PASSWORD:-postgres}"

write_env POSTGRES_HOST "$POSTGRES_HOST"
write_env POSTGRES_PORT "$POSTGRES_PORT"
write_env POSTGRES_DB "$POSTGRES_DB"
write_env POSTGRES_USER "$POSTGRES_USER"
write_env POSTGRES_PASSWORD "$POSTGRES_PASSWORD"

finish
}

run_wizard "$@"; exit

